$page['dir']='\\housekeeping';$page['housekeeping']=true;$page['rank']=5;require_once __DIR__ . '/../includes/core.php');require_once('./includes/hksession.php');$db=new Database();$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$q=trim((string)($_GET['q']??''));$like='%'.$q.'%';$users=$q===''?[]:$db->fetchAll('SELECT id,username,mail,ip_current FROM users WHERE username LIKE ? OR mail LIKE ? OR ip_current LIKE ? LIMIT 50',[$like,$like,$like]);$catalog=$q===''?[]:$db->fetchAll('SELECT id,catalog_name FROM catalog_items WHERE catalog_name LIKE ? OR id = ? LIMIT 50',[$like,(int)$q]);$reports=$q===''?[]:$db->fetchAll('SELECT id,reason,status FROM phpretro_user_reports WHERE reason LIKE ? OR evidence LIKE ? LIMIT 50',[$like,$like]);$page['name']='Admin search';$page['category']='tools';require_once('./templates/housekeeping_header.php');
?><div class="page_title"><span class="page_name">Admin search</span></div><div class="page_main"><div class="center"><form><input name="q" value="<?php echo $e($q);?>" placeholder="User, email, IP, catalogue item, report"><button>Search</button></form><?php if($q!==''){?><h2>Users</h2><ul><?php foreach($users as $r){?><li><?php echo(int)$r['id'].' '.$e($r['username']).' '.$e($r['mail']).' '.$e($r['ip_current']);?></li><?php }?></ul><h2>Catalogue</h2><ul><?php foreach($catalog as $r){?><li><?php echo(int)$r['id'].' '.$e($r['catalog_name']);?></li><?php }?></ul><h2>Reports</h2><ul><?php foreach($reports as $r){?><li>#<?php echo(int)$r['id'].' '.$e($r['reason']).' ('.$e($r['status']).')';?></li><?php }?></ul><?php }?></div></div><?php require_once('./templates/housekeeping_footer.php');?>